-- Sprint 46 / V4.7: fiscal controlado. Expansão idempotente e não destrutiva.
CREATE SCHEMA IF NOT EXISTS orcafacil;
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_company_profiles (id uuid PRIMARY KEY, account_id uuid NOT NULL, legal_name text NOT NULL, tax_document text NOT NULL, municipal_registration text, tax_regime text NOT NULL, city text NOT NULL, state char(2) NOT NULL, environment text NOT NULL DEFAULT 'Sandbox', readiness text NOT NULL DEFAULT 'Incomplete', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_company_profiles_account ON orcafacil.fiscal_company_profiles(account_id);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_provider_settings (id uuid PRIMARY KEY, account_id uuid NOT NULL, provider_name text NOT NULL, environment text NOT NULL, base_endpoint text, protected_token text, protected_webhook_secret text, status text NOT NULL DEFAULT 'NotConfigured', last_health_check_at timestamptz, last_error_summary text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_provider_settings_account ON orcafacil.fiscal_provider_settings(account_id);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_service_codes (id uuid PRIMARY KEY, account_id uuid NOT NULL, internal_code text NOT NULL, description text NOT NULL, municipal_code text NOT NULL, national_code text, default_rate numeric(9,4) NOT NULL CHECK(default_rate>=0), city text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_service_codes_account_code ON orcafacil.fiscal_service_codes(account_id,internal_code);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_tax_profiles (id uuid PRIMARY KEY, account_id uuid NOT NULL, name text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_customer_profiles (id uuid PRIMARY KEY, account_id uuid NOT NULL, customer_id uuid NOT NULL, person_type text NOT NULL, tax_document text NOT NULL, fiscal_email text, address text, city text, state char(2), retention_indicator boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_customer_profiles_tenant_customer ON orcafacil.fiscal_customer_profiles(account_id,customer_id);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_documents (id uuid PRIMARY KEY, account_id uuid NOT NULL, customer_id uuid NOT NULL, origin_type text NOT NULL, origin_id uuid NOT NULL, status text NOT NULL DEFAULT 'Draft', mode text NOT NULL, gross_amount numeric(18,2) NOT NULL CHECK(gross_amount>0), retention_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(retention_amount>=0), provider_reference text, authorization_protocol text, authorized_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(status <> 'Authorized' OR (provider_reference IS NOT NULL AND authorization_protocol IS NOT NULL)));
CREATE INDEX IF NOT EXISTS ix_fiscal_documents_account_status ON orcafacil.fiscal_documents(account_id,status);
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_documents_origin_active ON orcafacil.fiscal_documents(account_id,origin_type,origin_id) WHERE status NOT IN ('Canceled','Rejected','Failed');
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_document_events (id uuid PRIMARY KEY, account_id uuid NOT NULL, fiscal_document_id uuid NOT NULL, event_type text NOT NULL, actor_user_id uuid, sanitized_detail text, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_fiscal_document_events_tenant_document ON orcafacil.fiscal_document_events(account_id,fiscal_document_id,occurred_at);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_manual_authorization_events (id uuid PRIMARY KEY, account_id uuid NOT NULL, fiscal_document_id uuid NOT NULL, actor_user_id uuid NOT NULL, justification text NOT NULL CHECK(length(trim(justification))>=10), registered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_document_webhook_events (id uuid PRIMARY KEY, account_id uuid NOT NULL, provider text NOT NULL, provider_event_id text NOT NULL, event_type text NOT NULL, payload_hash text NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS ux_fiscal_webhook_provider_event ON orcafacil.fiscal_document_webhook_events(provider,provider_event_id);
CREATE TABLE IF NOT EXISTS orcafacil.fiscal_accounting_exports (id uuid PRIMARY KEY, account_id uuid NOT NULL, requested_by_user_id uuid NOT NULL, format text NOT NULL CHECK(format IN ('CSV','JSON')), period_start date NOT NULL, period_end date NOT NULL, file_asset_id uuid, row_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_fiscal_accounting_exports_account_created ON orcafacil.fiscal_accounting_exports(account_id,created_at DESC);
